css:
.window { border-radius: var(--window-radius); backdrop-filter: blur(16px) saturate(1.2); -webkit-backdrop-filter: blur(16px) saturate(1.2); background: rgba(226, 232, 240, 0.14); border: 1px solid rgba(255, 255, 255, 0.22); box-shadow: 0 24px 60px rgba(2, 6, 23, 0.45); overflow: hidden; }
.handle { background: linear-gradient(90deg, rgba(15, 23, 42, 0.78), rgba(30, 41, 59, 0.66)); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); border-bottom: 1px solid rgba(255, 255, 255, 0.18); }
#topbar { background: rgba(15, 23, 42, 0.5); backdrop-filter: blur(14px) saturate(1.15); -webkit-backdrop-filter: blur(14px) saturate(1.15); border-bottom: 1px solid rgba(255, 255, 255, 0.2); }
.app { border-radius: 16px; }
.app.selected { background: rgba(148, 163, 184, 0.24); box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.3); }
#runbar { border-radius: 14px; overflow: hidden; box-shadow: 0 14px 32px rgba(2, 6, 23, 0.45); }
.sidebar { background: rgba(15, 23, 42, 0.26); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); }
.sidebar li { background: rgba(226, 232, 240, 0.12); }
